(()=>{let t=self;t.addEventListener("push",i=>{let n=i.data?.json()??{title:"⏰ 주차 알림",body:"주차 시간을 확인하세요."};i.waitUntil(t.registration.showNotification(n.title,{body:n.body,icon:"/logo.png",badge:"/logo.png",tag:n.tag??"parking-alert",renotify:!0}))}),t.addEventListener("notificationclick",i=>{i.notification.close(),i.waitUntil(t.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t of i)if("focus"in t)return t.focus();return t.clients.openWindow("/")}))})})();